 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find monochrome rectangular frames (including patterned frames whose
    # colored interior remains connected to the border).
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            if not (all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0,c1+1)) and
                    all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0,r1+1))):
                continue
            inner = [[grid[y][x] for x in range(c0+1,c1)] for y in range(r0+1,r1)]
            n = sum(v != 0 for row in inner for v in row)
            frames.append(dict(color=color, r0=r0, r1=r1, c0=c0, c1=c1,
                               inner=inner, n=n, height=r1-r0+1, width=c1-c0+1))

    sources = [f for f in frames if f['n']]
    if not sources:
        return [row[:] for row in grid]
    # The patterned rectangle is the motif; only repeated, matching empty
    # frames are the destinations.
    source = max(sources, key=lambda f: f['n'])
    empties = [f for f in frames if f is not source and f['n'] == 0]
    groups = {}
    for f in empties:
        groups.setdefault((f['height'], f['width']), []).append(f)
    targets = [f for group in groups.values() if len(group) >= 2 for f in group]
    out = [row[:] for row in grid]
    src = source['inner']
    for f in targets:
        th, tw = f['height']-2, f['width']-2
        sh = len(src); sw = len(src[0]) if sh else 0
        # Copy the motif into the repeated frames. When a frame is one row
        # shorter, the motif's uppermost partial row is omitted and the open
        # row remains blank, as dictated by the frame pattern.
        if sh == th + 1 and sw == tw:
            patch = [[0]*tw] + [row[:] for row in src[1:th]]
        else:
            patch = [[0]*tw for _ in range(th)]
            for y in range(min(th, sh)):
                for x in range(min(tw, sw)):
                    patch[y][x] = src[y][x]
        for y in range(th):
            for x in range(tw):
                if patch[y][x]:
                    out[f['r0']+1+y][f['c0']+1+x] = f['color']
    return out
